import { sql } from 'drizzle-orm'
import { env, parseTrustedProxies, type ProxyMatcher } from '../env'
import { getDb } from '../db/client'
import { logger } from './logger'

/**
 * Security headers + CORS + rate limits (#74). No Cloudflare/WAF dependency.
 */

/**
 * Content Security Policy.
 *
 * script-src: in production every HTML response carries a fresh per-request nonce (generated by
 * the request middleware in src/start.ts and handed to the router as `ssr.nonce`), so TanStack
 * Start's hydration bootstrap, the theme pre-paint script and ScrollRestoration run, and nothing
 * else inline does. 'unsafe-inline' is kept only outside production, because Vite dev injects
 * inline scripts that carry no nonce. Without a nonce, scripts are limited to 'self'.
 *
 * style-src keeps 'unsafe-inline': React `style` attributes cannot carry a nonce. Do not add a
 * nonce to style-src, because browsers ignore 'unsafe-inline' once a nonce is present.
 *
 * No 'unsafe-eval': zod's eval probe is switched off in src/zod-config.ts (`jitless`).
 */
export function buildCsp(opts: { nonce?: string; production?: boolean } = {}): string {
  const production = opts.production ?? env().NODE_ENV === 'production'
  const scriptSrc = !production ? "script-src 'self' 'unsafe-inline'" : opts.nonce ? `script-src 'self' 'nonce-${opts.nonce}'` : "script-src 'self'"
  return [
    "default-src 'self'",
    scriptSrc,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "connect-src 'self'",
    // data: for small fonts Vite inlines into the CSS (for example a JetBrains Mono subset).
    "font-src 'self' data:",
    "object-src 'none'",
    "base-uri 'self'",
    "frame-ancestors 'none'",
    "form-action 'self'",
  ].join('; ')
}

/** A CSP nonce: 16 random bytes, base64. New for every request. */
export function newCspNonce(): string {
  return Buffer.from(crypto.getRandomValues(new Uint8Array(16))).toString('base64')
}

export function securityHeaders(isHttps: boolean, nonce?: string): Record<string, string> {
  const h: Record<string, string> = {
    'Content-Security-Policy': buildCsp({ nonce }),
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'X-Frame-Options': 'DENY',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
    'Cross-Origin-Opener-Policy': 'same-origin',
  }
  if (isHttps) h['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'
  return h
}

/** Allowed cross-origin callers: APP_URL's origin plus CORS_ALLOWED_ORIGINS. Never `*`. */
export function allowedOrigins(): Set<string> {
  const e = env()
  const out = new Set<string>([new URL(e.APP_URL).origin])
  for (const o of (e.CORS_ALLOWED_ORIGINS ?? '').split(',')) {
    const t = o.trim()
    if (!t || t === '*') continue
    try {
      out.add(new URL(t).origin)
    } catch {
      /* ignore malformed */
    }
  }
  return out
}

export function corsHeaders(origin: string | null): Record<string, string> | null {
  if (!origin || !allowedOrigins().has(origin)) return null
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Credentials': 'true',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'content-type, x-request-id',
    Vary: 'Origin',
  }
}

export interface RateLimitResult {
  ok: boolean
  retryAfterSec: number
}

/** What the request middleware calls. Both limiters below implement it. */
export interface AsyncRateLimiter {
  check(key: string, now?: number): Promise<RateLimitResult>
}

/**
 * Fixed-window in-memory limiter. Per replica: with N replicas the effective limit is N x limit.
 * Used when RATE_LIMIT_STORAGE=memory, and by tests. Auth endpoints use Better Auth's own limiter.
 */
export class RateLimiter {
  private hits = new Map<string, { count: number; resetAt: number }>()
  constructor(
    private readonly limit: number,
    private readonly windowMs = 60_000,
  ) {}

  check(key: string, now = Date.now()): RateLimitResult {
    const cur = this.hits.get(key)
    if (!cur || cur.resetAt <= now) {
      this.hits.set(key, { count: 1, resetAt: now + this.windowMs })
      if (this.hits.size > 10_000) this.sweep(now)
      return { ok: true, retryAfterSec: 0 }
    }
    cur.count++
    return cur.count > this.limit ? { ok: false, retryAfterSec: Math.ceil((cur.resetAt - now) / 1000) } : { ok: true, retryAfterSec: 0 }
  }

  private sweep(now: number) {
    for (const [k, v] of this.hits) if (v.resetAt <= now) this.hits.delete(k)
  }
}

/**
 * Fixed-window limiter on app_rate_limits, shared by every replica. One atomic upsert per check:
 * a new key starts at 1, an expired window restarts at 1, otherwise the count goes up by one.
 * Window time comes from the database clock (`now()`) so replicas with drifting clocks agree;
 * tests may pass `now` explicitly.
 *
 * Fails open: if the database errors, the request is allowed and a warning is logged. Chat still
 * requires a signed-in session and the database itself, so a limiter outage should not take chat
 * down on its own; the auth limiter (Better Auth) is separate and unaffected.
 */
export class DbRateLimiter implements AsyncRateLimiter {
  private calls = 0
  constructor(
    private readonly limit: number,
    private readonly windowMs = 60_000,
    private readonly prefix = 'chat:',
  ) {}

  async check(key: string, now?: number): Promise<RateLimitResult> {
    const k = `${this.prefix}${key}`
    const ts = now === undefined ? sql`now()` : sql`${new Date(now).toISOString()}::timestamptz`
    const win = sql`(${this.windowMs}::int * interval '1 millisecond')`
    try {
      const res = (await getDb().execute(sql`
        insert into app_rate_limits as r (key, count, window_started_at, expires_at) values (${k}, 1, ${ts}, ${ts} + ${win})
        on conflict (key) do update set
          count = case when r.window_started_at <= ${ts} - ${win} then 1 else r.count + 1 end,
          window_started_at = case when r.window_started_at <= ${ts} - ${win} then ${ts} else r.window_started_at end,
          expires_at = case when r.window_started_at <= ${ts} - ${win} then ${ts} + ${win} else r.window_started_at + ${win} end
        returning count, ceil(extract(epoch from (window_started_at + ${win} - ${ts})))::int as retry_after_sec
      `)) as unknown as RateRow[] | { rows: RateRow[] }
      const row = Array.isArray(res) ? res[0] : res.rows[0]
      if (++this.calls % 500 === 0) void this.sweep()
      const count = Number(row?.count ?? 1)
      return count > this.limit ? { ok: false, retryAfterSec: Math.max(1, Number(row?.retry_after_sec ?? 1)) } : { ok: true, retryAfterSec: 0 }
    } catch (err) {
      logger.warn('rate limiter database error; allowing request', { error: err instanceof Error ? err.message : String(err) })
      return { ok: true, retryAfterSec: 0 }
    }
  }

  /**
   * Drop rows whose own window has ended, so the table stays small. Each row carries its expiry, so
   * a short-window limiter never deletes a live bucket of a longer-window limiter. Best effort.
   */
  async sweep(now?: number) {
    const ts = now === undefined ? sql`now()` : sql`${new Date(now).toISOString()}::timestamptz`
    try {
      await getDb().execute(sql`delete from app_rate_limits where expires_at < ${ts}`)
    } catch {
      /* best effort */
    }
  }
}
type RateRow = { count: number | string; retry_after_sec: number | string | null }

/**
 * Client key for rate limiting: walk X-Forwarded-For from the right, skipping hops listed in
 * TRUSTED_PROXIES (IPs or CIDR ranges), and use the first untrusted hop. Without TRUSTED_PROXIES
 * the right-most hop is used (the one the nearest proxy appended). Clients cannot choose a bucket by
 * prepending entries; they could only add entries to the left, which are ignored.
 */
export function clientKey(request: Request, trusted: ProxyMatcher = trustedProxies()) {
  return clientIp(request.headers, trusted) ?? 'local'
}

/**
 * The client IP by the same rule, or null without X-Forwarded-For. X-Real-IP is never read: a
 * client can send it, and Container Apps ingress does not overwrite it (#196). Also used for the
 * sign-in limiter and auth audit rows (server/auth/auth.ts).
 */
export function clientIp(headers: Headers, trusted: ProxyMatcher = trustedProxies()): string | null {
  const hops = (headers.get('x-forwarded-for') ?? '').split(',').map((h) => h.trim()).filter(Boolean)
  for (let i = hops.length - 1; i >= 0; i--) {
    if (!trusted.has(hops[i]!)) return hops[i]!
  }
  return hops[0] ?? null
}

let proxies: { source: string | undefined; matcher: ProxyMatcher } | undefined
function trustedProxies(): ProxyMatcher {
  const source = env().TRUSTED_PROXIES
  if (!proxies || proxies.source !== source) proxies = { source, matcher: parseTrustedProxies(source).matcher }
  return proxies.matcher
}

let chatLimiter: AsyncRateLimiter | undefined
/** Per-client limiter for /api/chat: database-backed (shared) unless RATE_LIMIT_STORAGE=memory. */
export function chatRateLimiter(): AsyncRateLimiter {
  if (!chatLimiter) {
    const e = env()
    if (e.RATE_LIMIT_STORAGE === 'memory') {
      const mem = new RateLimiter(e.RATE_LIMIT_CHAT_PER_MIN)
      chatLimiter = { check: async (key, now) => mem.check(key, now) }
    } else {
      chatLimiter = new DbRateLimiter(e.RATE_LIMIT_CHAT_PER_MIN)
    }
  }
  return chatLimiter
}

export function resetChatRateLimiterForTests() {
  chatLimiter = undefined
}
